from fractions import *

def main():
	T = int(input())
	for t in range(T):
		(N, M) = [int(x) for x in input().split()]
		A = []
		for i in range(N):
			row = input().split()
			for j in range(len(row)):
				if '.' not in row[j]:
					while True:
						y = 1
				row[j] = int(10000 * (eval(row[j]) + 2e-05))
			A.append(row)
		Pw = 1
		for j in range(M):
			Pw *= A[0][j]
			if Pw == 0:
				break
		if Pw == 0:
			print('0.000000')
			continue
		wins = Pw
		for i in range(1, N):
			tmp = 1
			for j in range(M):
				tmp *= A[i][j]
				if tmp == 0:
					break
			wins += tmp
		print('%0.6f' % Fraction(Pw / wins))
main()
